style.css:
@-moz-document domain("youtube.com") {
/* 1. Set the main background image */
  html, body, #page-manager, ytd-app {
    background: url("https://pinimg.com") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* 2. Clear out solid background containers */
  ytd-browse, 
  ytd-watch-flexy, 
  #contentContainer,
  #page-manager ytd-browse[page-subtype="home"],
  #columns,
  #primary,
  #secondary {
    background: transparent !important;
  }

  /* 3. Add a red overlay to panels for readability */
  ytd-rich-grid-renderer, 
  #primary-inner, 
  #secondary-inner,
  #watch7-container,
  ytd-playlist-panel-renderer {
    background: rgba(45, 10, 15, 0.75) !important;
    padding: 15px !important;
    border-radius: 12px !important;
  }

  /* 4. Make the top header bar match the red aesthetic with a blur effect */
  #masthead-container, ytd-masthead {
    background: rgba(30, 5, 10, 0.85) !important;
    backdrop-filter: blur(10px) !important;
  }

  /* 5. Make the left sidebar match the red aesthetic */
  #guide-content, ytd-guide-renderer, ytd-mini-guide-renderer {
    background: rgba(30, 5, 10, 0.85) !important;
  }

  /* 6. Tint individual video cards and search bars slightly to blend in */
  ytd-searchbox #container {
    background: rgba(20, 5, 5, 0.6) !important;
  }
}
